package com.aicharacter.v3;import org.json.*;
public final class GodMessage{public String messageId,sourceEventId,priority,text;public long timestamp;public boolean read,delivered;public GodMessage(String id,String src,String p,String t,long time){messageId=id;sourceEventId=src;priority=p;text=t;timestamp=time;}public JSONObject toJson(){JSONObject j=new JSONObject();try{j.put("messageId",messageId);j.put("sourceEventId",sourceEventId);j.put("priority",priority);j.put("text",text);j.put("timestamp",timestamp);j.put("read",read);j.put("delivered",delivered);}catch(Exception ignored){}return j;}public static GodMessage fromJson(JSONObject j){GodMessage m=new GodMessage(j.optString("messageId"),j.optString("sourceEventId"),j.optString("priority"),j.optString("text"),j.optLong("timestamp"));m.read=j.optBoolean("read");m.delivered=j.optBoolean("delivered");return m;}}
